// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;

    // the test contract is the deployer of c, hence c.creator == address(this);
    // accept ETH so that a transfer to the creator cannot be what reverts
    receive() external payable {}

    function setUp() public { c = new Wallet(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(this));
        vm.assume(actor != address(0));
        amount = bound(amount, 1, type(uint128).max);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        uint256 creatorBalBefore = address(this).balance;

        vm.prank(actor);
        try c.withdraw(amount) {
            // GENERAL RULE: a successful withdrawal must not enrich the creator;
            // the withdrawn ETH goes to the caller, not the creator.
            assertTrue(address(this).balance == creatorBalBefore);
        } catch {
            // withdrawal legitimately failing is admissible and reveals nothing
            assertTrue(true);
        }
    }
}
